<?php $CVS_Version = '$Revision: 1.6 $ ; $Date: 2008/07/01 08:47:12 $';// обработчик торговлиclass EH_Trading extends EH_Event{    /**     * ОБект торга     *     * @var DE_TradeLot     */    private $tradeLot;        /**     * Экземпляр ивента скоторым работаем     *     * @var DE_EventQueue     */    private $eventQueue;        /**     * Объект непосредственно самого товара     *     * @var DE_TradeGoodInterface     */    private $tradeGood;        /**     * Enter description here...     *     * @var string     */    private $tradeCategoryName;         function __construct()    {        parent::EH_Event();    }    function handleEvent($eqid)    {        assert(is_int($eqid) && $eqid > 0);        $this->eqid = $eqid;                $this->getEventParams();                $this->eventQueue = DE_EventQueue::CreateFromID($this->eqid);                   if(!$this->checktime)         {            $this->checktime = 'now()';        }                       $tradeLotID =  (int)$this->eventparams['ID_TradeLot'];        if ($tradeLotID <=0) {            $this->eventQueue->setIsTrash(true);            return true;        }                //тут защита ситуации когда есть ивент торговли, но нет         //для него тога. Куда проебываеться непоняно.        $tradeLotData = DS_Trade::GetTradeLotByID($tradeLotID);         if(count($tradeLotData) == 0)        {            $str = "LotID = $tradeLotID";            SU_DebugTools::LogAll($str, "TradeEventWithoutTrade.log");                        if(DE_EventQueue::CreateFromID($this->eqid)->isLockedForHandl())            {                DS_ClientLockHandler('USER_LOCK_DELAY', constant('USER_LOCK_DELAY'), $this->eqid, 'EVENT_QUEUE');                                   }                           $this->eventQueue->setIsTrash(true);            return true;        }                        $this->tradeLot = DE_TradeLot::CreateFromID($tradeLotID, $tradeLotData);                $this->tradeCategoryName = DS_Trade::GetTradeCategoryNameByID($this->tradeLot->getTradeType()->getTradeFromCategoryID());        assert(!empty($this->tradeCategoryName));                $this->tradeGood = ME_TradeCreateGoodObjet::Exec($this->tradeCategoryName, $this->tradeLot->getArticleID());                // если закончено        if ($this->_isTimeToHandle())         {            $this->_handle();        }else{            $this->_preHandle();        }                return true;        }            private function _preHandle()    {        $messparams[0] = "{b}".$this->tradeGood->getLocalizedName()."{/b}";        $messparams[1] = "{b}".GB_Integer::Format($this->tradeLot->getAmount(), ' ')."{/b}";        $messparams[2] = "{b}".$this->tradeLot->getTradeType()->getToArticle()->getLocolizedName()."{/b}";        $messparams[3] = "{b}".GB_Integer::Format($this->tradeLot->getCurrentPrice(), ' ')."{/b}";        $messparams[4] = "{b}".$this->tradeLot->getSellerComb()->getFullName()."{/b}";        $messparams[5] = "{b}".DS_Trade::GetLocalizedTradeScope($this->tradeLot->getTradeScopeID())."{/b}";        $messparams[6] = $this->_getTimePeriodToEnd()->getDSFormat();                $checkDate = GB_TypeFactory::CreateBase('GB_Date', time());        //До окончания торга %(%) за %(%) с соты %(%) осталось %;        DE_SystemMessages::AddMessageFromMessageCompiler($checkDate, $this->tradeLot->getSeller()->getID(), "TRADE_LOT_NOT_FINISHED", $messparams, 0, 'YELLOW', 'NO_ACCUMULATE');        // Если уже есть покупатель        if ($this->tradeLot->haveCurrentCustomer() === true) {            $messparams[4] = $messparams[6];            unset($messparams[5]);            unset($messparams[6]);            //До окончания торга %(%) за %(%) осталось %            DE_SystemMessages::AddMessageFromMessageCompiler($checkDate, $this->tradeLot->getCurrentCustomer()->getID(), "TRADE_LOT_NOT_FINISHED_ANONIMUS", $messparams, 0, 'YELLOW', 'NO_ACCUMULATE');        }    }        private function _handle()    {        // Перезаписываем чекдейт, что бы в системных сообщениях было верное время        $this->checktime = $this->tradeLot->getEndDate()->getPgFormat();                if(DE_EventQueue::CreateFromID($this->eqid)->isLockedForHandl())        {            DS_ClientLockHandler('USER_LOCK_DELAY', constant('USER_LOCK_DELAY'), $this->eqid, 'EVENT_QUEUE');                               }                                       //Если товра аукцион и он иммет ставик то тогда доставляем его        if($this->tradeLot->haveCurrentCustomer())        {            $this->_sendGoodAndPayment();        }else{            $this->_returnLotToSeller();        }                    $this->eventQueue->setIsTrash(true);                    }        private function _sendGoodAndPayment()    {                   //Продаем лот        $bayResult = ME_TradeExecLotBay::Exec($this->tradeLot, $this->eventQueue->getEndDate(), $this->tradeLot->getbuyAnonymous());                //Поставили флаг что есть ивенты новые поражденные этим ивентом         $this->new = 1;                //Заносим в список созданных ивентов ивент доставки товара        $this->newevents[] = array('id_eventqueue' => $bayResult->getDeliveryGoodEvent()->getID());                //Если есть ивент тоставки оплаты то и его        if($bayResult->getDeliveryPaymentEvent() instanceof DE_EventQueue)        {            $this->newevents[] = array('id_eventqueue' => $bayResult->getDeliveryPaymentEvent()->getID());        }    }        private function _returnLotToSeller()    {        ME_TradeExecLotReturn::Exec($this->tradeLot,  GB_TypeFactory::CreateBase('GB_Date', $this->eventendtime));                        $messparams[0] = "{b}".$this->tradeGood->getLocalizedName()."{/b}";        $messparams[1] = "{b}".GB_Integer::Format($this->tradeLot->getAmount(), ' ')."{/b}";        $messparams[2] = "{b}".$this->tradeLot->getTradeType()->getToArticle()->getLocolizedName()."{/b}";        $messparams[3] = "{b}".GB_Integer::Format($this->tradeLot->getPrice(), ' ')."{/b}";        $messparams[4] = "{b}".$this->tradeLot->getSellerComb()->getFullName()."{/b}";                    //Торговый лот %(%) за %(%) возвращен на соту %.        DE_SystemMessages::AddMessageToEventParticipants($this->eqid, "TRADE_LOT_RETURNED", $messparams, 0, 'YELLOW');    }    }?>